mapper.select:
SELECT
FROM ( SELECT manifest.manifest_version::BIGINT AS version, manifest.updated_at AS updated_at, CONCAT_WS('|', 'manifest', manifest.id::TEXT, manifest.manifest_version::TEXT, manifest.manifest_hash) AS fingerprint FROM ( SELECT id, manifest_version, manifest_hash, updated_at FROM offline_package_manifest WHERE incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler} ORDER BY manifest_version DESC LIMIT 1 ) manifest UNION ALL SELECT op.version AS version, op.updated_at AS updated_at, CONCAT_WS('|', 'op', op.id::TEXT, op.status, op.version::TEXT) AS fingerprint FROM operational_period op WHERE op.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler} UNION ALL SELECT 1::BIGINT AS version, assignment.updated_at AS updated_at, CONCAT_WS('|', 'assignment', assignment.id::TEXT, assignment.status, assignment.updated_at::TEXT) AS fingerprint FROM search_area_assignment assignment JOIN search_area area ON area.id = assignment.search_area_id
JOIN police_phone phone ON phone.account_id = assignment.assigned_account_id AND phone.id = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
WHERE assignment.status = 'ACTIVE' AND assignment.revoked_at IS NULL
AND area.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
UNION ALL SELECT marker.version AS version, marker.updated_at AS updated_at, CONCAT_WS('|', 'initial-marker', marker.id::TEXT, marker.status, marker.version::TEXT) AS fingerprint FROM marker WHERE marker.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND marker.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND marker.marker_source IN ('MOCK_SEED', 'SYSTEM') AND marker.status IN ('ACTIVE', 'UPDATED') ) source
